import{c as t,Q as e,j as n,m as s}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"GetTransDataMaxMinTmpSize","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetTransDataMaxMinTmpSize","slug":"gettransdatamaxmintmpsize"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/张量变换/GetTransDataMaxMinTmpSize.md","filePath":"api/SIMD-API/高阶API/张量变换/GetTransDataMaxMinTmpSize.md"}'),i={name:"api/SIMD-API/高阶API/张量变换/GetTransDataMaxMinTmpSize.md"};function l(r,a,p,d,o,c){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="gettransdatamaxmintmpsize" tabindex="-1">GetTransDataMaxMinTmpSize <a class="header-anchor" href="#gettransdatamaxmintmpsize" aria-label="Permalink to &quot;GetTransDataMaxMinTmpSize&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>kernel侧TransData接口的计算需要开发者预留/申请临时空间，本接口用于在host侧获取预留/申请的最大最小临时空间大小，开发者基于此范围选择合适的空间大小作为Tiling参数传递到kernel侧使用。</p><ul><li>为保证功能正确，预留/申请的临时空间大小不能小于最小临时空间大小。</li><li>在最小临时空间-最大临时空间范围内，随着临时空间增大，kernel侧接口计算性能会有一定程度的优化提升。为了达到更好的性能，开发者可以根据实际的内存使用情况进行空间预留/申请。该接口<strong>最大临时空间当前等于最小临时空间</strong>。</li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bool GetTransDataMaxMinTmpSize(const platform_ascendc::PlatformAscendC&amp; platform, const ge::Shape&amp; srcShape, const ge::Shape&amp; dstShape,const ge::DataType dataType, const TransDataConfig &amp;config, uint32_t&amp; maxValue, uint32_t&amp; minValue)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 接口参数列表</p><table tabindex="0"><thead><tr><th>接口</th><th>输入/输出</th><th>功能</th></tr></thead><tbody><tr><td>platform</td><td>输入</td><td>传入硬件平台的信息，PlatformAscendC定义请参见构造及析构函数。</td></tr><tr><td>srcShape</td><td>输入</td><td>输入源操作数的shape大小，参数取值与TransData接口的params.srcLayout参数中的shape信息保持一致。</td></tr><tr><td>dstShape</td><td>输入</td><td>输出目的操作数的shape大小，参数取值与TransData接口的params.dstLayout参数中的shape信息保持一致。</td></tr><tr><td>dataType</td><td>输入</td><td>输入的数据类型，ge::DataType类型，当前只支持half/float/uint16_t/int16_t数据类型的输入。</td></tr><tr><td>config</td><td>输入</td><td>数据格式转换的场景，参数取值与TransData接口的config参数保持一致。当前支持的转换场景有：NCDHW -&gt; NDC1HWC0、NDC1HWC0 -&gt; NCDHW、NCDHW -&gt; FRACTAL_Z_3D、FRACTAL_Z_3D -&gt; NCDHW。TransDataConfig类型，具体定义如下。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen1119148131414&quot;&gt;struct TransDataConfig { DataFormat srcFormat; DataFormat dstFormat; }; enum class DataFormat : uint8_t { ND = 0, NZ, NCHW, NC1HWC0, NHWC, NCDHW, NDC1HWC0, FRACTAL_Z_3D, };&lt;/pre&gt;</td></tr><tr><td>maxValue</td><td>输出</td><td>TransData接口能完成计算所需的最大临时空间大小，超出该值的空间不会被该接口使用。 说明： maxValue仅作为参考值，有可能大于Unified Buffer剩余空间的大小，该场景下，开发者需要根据Unified Buffer剩余空间的大小来选取合适的临时空间大小。</td></tr><tr><td>minValue</td><td>输出</td><td>TransData接口能完成计算所需最小临时空间大小。为保证功能正确，接口计算时预留/申请的临时空间不能小于该数值。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>GetTransDataMaxMinTmpSize返回值为true/false，true表示成功获取TransData接口内部计算需要的最大和最小临时空间大小；false表示获取失败。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整的调用样例请参考<a href="./../数学计算/更多样例-83.html">更多样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 输入shape为(1,16,2,4,4)NCDHW转换为输出shape(1,2,1,4,4,16)NDC1HWC0;算子输入的数据类型为half</span></span>
<span class="line"><span>uint32_t maxSize;</span></span>
<span class="line"><span>uint32_t minSize;</span></span>
<span class="line"><span>int32_t n = 1, c = 16, d = 2, h = 4, w = 4, c1 = 1, c0 = 16;</span></span>
<span class="line"><span>auto ncdhwShape = ge::Shape({ n, c, d, h, w });</span></span>
<span class="line"><span>auto ndc1hwc0Shape = ge::Shape({ n, d, c1, h, w, c0});</span></span>
<span class="line"><span>auto plat = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>TransDataConfig config = {DataFormat::NCDHW, DataFormat::NDC1HWC0};</span></span>
<span class="line"><span>bool ret = GetTransDataMaxMinTmpSize(plat, ncdhwShape, ndc1hwc0Shape, ge::DataType::DT_FLOAT16, config, maxSize, minSize);</span></span></code></pre></div>`,16)])])}const u=t(i,[["render",l]]);export{m as __pageData,u as default};
